/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile
source = r'''
#include \"service.hpp\"
#include <cassert>
int main() {
    assert(csvField(\"\\\"\\\"\") == \"\\\"\\\"\\\"\\\"\\\"\\\"\");
    assert(csvField(\"a,\\r\\nb\") == \"\\\"a,\\r\\nb\\\"\");
    std::string input;
    for (int i = 0; i < 256; ++i) input += static_cast<char>(i);
    const auto output = csvField(input);
    assert(output.size() == input.size() + 3);
    assert(output.front() == '\"' && output.back() == '\"');
    std::size_t pos = 1;
    for (char c : input) {
        assert(output[pos++] == c);
        if (c == '\"') assert(output[pos++] == '\"');
    }
    assert(pos == output.size() - 1);
}
'''
with tempfile.TemporaryDirectory(prefix='csvfield-') as temp:
    binary = str(pathlib.Path(temp) / 'check')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-I.', '-x', 'c++', '-', '-o', binary], input=source, text=True, check=True)
    subprocess.run([binary], check=True)
print('CSV edge cases and all 256 byte values passed.')
PY"

